"""Communication Module"""

from __future__ import annotations

import datetime
import logging
import threading
from typing import Union, List, TYPE_CHECKING

import pytz
import lxml.etree

from taf.internal.rfsw.regexdeepdiff.regexdeepdiff import RegexDeepDiffException

from taf.ul.oran_mplane.core.generation import Generation
from taf.ul.oran_mplane.core.libraries.RegexDeepDiffWrapper import RegexDeepDiffWrapper

if TYPE_CHECKING:
    from taf.ul.oran_mplane.interface import OranMplane
    from ncclient.transport.notify import Notification


class CommunicationException(Exception):
    """CommunicationException"""


class Communication:
    """Communication class"""

    def __init__(self, manager: OranMplane, logger=None):
        self.logger = logging.getLogger(__name__) if logger is None else logger
        self.manager = manager
        self.sessions = manager.connection.sessions
        self.notifications_buffer: dict[str, list[Notification]] = {}
        self.supervision_buffer: dict[str, list[Notification]] = {}
        self.notifications_lock = threading.Lock()
        self.validation = RegexDeepDiffWrapper(logger)
        self.generation = Generation(logger)

    @property
    def library_wrapper(self) -> dict:
        """Get Connection.library_wrapper up-to-date state."""
        return self.manager.connection.library_wrapper

    def _get_via_xpath(self, session, content, with_defaults=None):
        """get_via_xpath method
        :param session:
        :param content:
        :param with_defaults
        :return:
        """
        msg_filter = (
            f'<filter type="xpath" xmlns:ns="{content["namespace"]}"' f' select="/ns:{content["expression"]}"/>'
        )
        self.logger.debug(f"Netconf/Yang get msg in xpath format send RM:\n {msg_filter}")
        response = self.library_wrapper[session].get_xpath(msg_filter, with_defaults)
        return response

    def _get_via_xml(self, session, content, with_defaults=None):
        """get_via_xml method
        :param session:
        :param content:
        :param with_defaults
        :return:
        """
        self.validation.validate_xml(content)
        self.logger.debug(f"Netconf/Yang get msg in xml format send to RM:\n {content}")
        return self.library_wrapper[session].get_subtree(content, with_defaults)

    def get_without_filter(self, session, with_defaults=None):
        """get_without_filter method
        :param session:
        :param with_defaults
        :return:
        """
        self.logger.debug("Netconf/Yang get without filtering will be send")
        output = self.library_wrapper[session].get_without_filter(with_defaults)
        self.logger.debug(output)
        return output

    def _get_via_dictionary(self, session: str, content: dict, with_defaults=None):
        """_get_via_dictionary method
        :param session:
        :param content:
        :param with_defaults
        :return:
        """
        content = self.generation.generate_xml_from_dict(content)
        self.validation.validate_xml(content)
        self.logger.debug(f"Netconf/Yang get msg in xml format send to RM:\n {content}")
        return self.library_wrapper[session].get_subtree(content, with_defaults)

    def _get(self, session, request, msg_format="xml", with_defaults=None):
        if msg_format == "xml":
            return self._get_via_xml(session, request, with_defaults)
        if msg_format == "xpath":
            return self._get_via_xpath(session, request, with_defaults)
        if msg_format == "dictionary":
            return self._get_via_dictionary(session, request, with_defaults)
        raise CommunicationException(f"{msg_format} is not a supported format.")

    # pylint: disable=too-many-arguments
    def get(
        self,
        session,
        msg_format,
        msg,
        validation_mode: str = "deepdiff",
        exclude_paths: Union[None, List[str]] = None,
        with_defaults=None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ):
        """get method
        :param session: Session that requestr will be sent to, e.g. "master_0"
        :param msg_format: What format is message, xml, dictionary or xpath directory.
        :param msg: Message that will be used to send request to radio.
        :param validation_mode: What will be used for validation of response. enum ["string", "deepdiff"]
         or if needed validation can be skipped by using "skip_validation".
        :param exclude_paths: what paths will be excluided from validation. eg: root['rpc-reply']['@message-id']
        :param with_defaults:
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
                log_type_mismatch - additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return: tuple of (timestamp, content) for the rpc reply
        """
        request = msg["request"]
        response = self._get(session, request, msg_format, with_defaults)
        timestamp = getattr(response, "timestamp", datetime.datetime.now().astimezone())  # in case of tls
        if validation_mode == "skip_validation":
            response = str(response)
            self.logger.debug(f"response: {response}")
            return timestamp, response
        expected_response = msg["expected_response"]
        return timestamp, self.validation.validate_output(
            expected_response=expected_response,
            response=response,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    # pylint: disable=too-many-arguments
    def edit_config(
        self,
        session,
        msg,
        target="running",
        default_operation=None,
        test_option="set",
        error_option="continue-on-error",
        msg_format: str = "xml",
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> tuple[datetime, str]:
        """
        edit_config method
        :param session: Session that requestr will be sent to, e.g. "master_0"
        :param msg: Message that will be used to send request to radio.
        :param target: The datastore to edit
        :param default_operation: The default-operation to perform; can be `None`, 'merge', 'replace', or 'none'.
        :param test_option: The test-option to use; can be `None`, 'test-then-set', 'set', or 'test-only'
        :param error_option: Can be `None`, 'stop-on-error', 'continue-on-error', or 'rollback-on-error'
        :param msg_format: ["xml", "dictionary"]
        :param validation_mode: What will be used for validation of response. enum ["string", "deepdiff"]
         or if needed validation can be skipped by using "skip_validation".
        :param exclude_paths: what paths will be excluided from validation. eg: root['rpc-reply']['@message-id']
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
                log_type_mismatch - additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return: tuple of (timestamp, content) for the rpc reply
        """
        request = msg["request"]
        response = self._edit_config(
            session=session,
            request=request,
            target=target,
            default_operation=default_operation,
            test_option=test_option,
            error_option=error_option,
            msg_format=msg_format,
        )
        timestamp = getattr(response, "timestamp", datetime.datetime.now().astimezone())  # in case of tls
        if validation_mode == "skip_validation":
            response = str(response)
            self.logger.debug(f"Output: {response}")
            return timestamp, response
        expected_response = msg.get("expected_response", "<ok/>")
        return timestamp, self.validation.validate_output(
            expected_response=expected_response,
            response=response,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    # pylint: disable=too-many-arguments
    def _edit_config(
        self,
        session: str,
        request: str | dict,
        target: str,
        default_operation: str,
        test_option: str,
        error_option: str,
        msg_format: str,
    ) -> str | dict:
        """Send edit message based on provided format.

        :param session: Session that requestr will be sent to, e.g. "master_0"
        :param request: Message that will be used to send request to radio.
        :param target: The datastore to edit
        :param default_operation: The default-operation to perform; can be `None`, 'merge', 'replace', or 'none'.
        :param test_option: The test-option to use; can be `None`, 'test-then-set', 'set', or 'test-only'
        :param error_option: Can be `None`, 'stop-on-error', 'continue-on-error', or 'rollback-on-error'
        :param msg_format: ["xml", "dictionary"]
        :return:
        """
        if msg_format == "xml":
            return self._edit_config_via_xml(
                session=session,
                request=request,
                target=target,
                default_operation=default_operation,
                test_option=test_option,
                error_option=error_option,
            )
        if msg_format == "dictionary":
            return self._edit_config_via_dictionary(
                session=session,
                request=request,
                target=target,
                default_operation=default_operation,
                test_option=test_option,
                error_option=error_option,
            )
        raise CommunicationException(f"{msg_format} is not a supported format.")

    def _edit_config_via_xml(self, session, request, target, default_operation, test_option, error_option):
        """_edit_config_via_xml method
        :param session:
        :param request
        :param target
        :param default_operation
        :param test_option
        :param error_option
        :return: Received response.
        """
        self.validation.validate_xml(request)
        request = f"<config>{request}</config>"
        self.logger.debug(f"Netconf/Yang edit_config msg in xml format send to RM:\n {request}")
        return self.library_wrapper[session].edit_config(
            request,
            target,
            default_operation,
            test_option,
            error_option,
            msg_format="xml",
        )

    def _edit_config_via_dictionary(self, session, request, target, default_operation, test_option, error_option):
        """_edit_config_via_dictionary method
        :param session:
        :param request
        :param target
        :param default_operation
        :param test_option
        :param error_option
        :return: Received response.
        """
        request = self.generation.generate_xml_from_dict(request)
        self.validation.validate_xml(request)
        request = f"<config>{request}</config>"
        self.logger.debug(f"Netconf/Yang edit_config msg in xml format send to RM:\n {request}")
        return self.library_wrapper[session].edit_config(
            request,
            target,
            default_operation,
            test_option,
            error_option,
            msg_format="xml",
        )

    def create_subscription(self, session, noti_filter, stream_name, timeout):
        """create_subscription
        :param session:
        :param noti_filter:
        :param stream_name:
        :param timeout:
        :return:
        """
        start_time, stop_time = self._calculate_start_and_stop_time(timeout)
        return self.library_wrapper[session].create_subscription(noti_filter, stream_name, start_time, stop_time)

    def collect_notification(  # noqa: C901
        self,
        session: str,
        timeout: int,
        expected_notification: Union[str, dict],
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
        notification_expected=True,
        reversed_order: bool = False,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> Union[Notification, str]:
        """collect_notification
        :param session:
        :param timeout:
        :param expected_notification:
        :param validation_mode: enum ["string", "deepdiff"]
        :param exclude_paths:
        :param notification_expected:
        :param reversed_order: flag which indicates whether notifications in buffer should be matched from:
            * reversed_order=True latest to earliest,
            * reversed_order=False earliest to latest.
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
                exclude_regex_paths: list of path regexes to exclude in deepdiff.
        :return:
        """
        if (
            "supervision-notification" in str(expected_notification)
            and session in self.manager.procedures.supervision_threads
        ):
            raise CommunicationException(
                f"Supervision notification {expected_notification} is not expected to be collected manually while "
                f"supervision thread is running for session {session}."
            )
        matched = None
        current = datetime.datetime.utcnow()
        stop = current + datetime.timedelta(seconds=timeout)
        buffer = (
            self.notifications_buffer.setdefault(session, [])
            if "supervision-notification" not in str(expected_notification)
            else self.supervision_buffer.setdefault(session, [])
        )
        while current < stop:
            current = datetime.datetime.utcnow()
            self.collect_all_notifications(session)
            if buffer:
                for notification in reversed(buffer.copy()) if reversed_order else buffer.copy():
                    try:
                        self.validation.validate_output(
                            expected_response=expected_notification,
                            response=notification.notification_xml,
                            validation_mode=validation_mode,
                            exclude_paths=exclude_paths,
                            log_type_mismatch=True,
                            ignore_dictionary_item_added=ignore_dictionary_item_added,
                            ignore_iterable_item_added=ignore_iterable_item_added,
                            log_ignored_items=False,
                            **kwargs,
                        )
                        matched = notification
                        buffer.remove(notification)
                        current = stop
                        break
                    except RegexDeepDiffException:
                        continue
        if not matched and buffer:
            self.logger.debug(f"Collected notifications:\n{[notif.notification_xml for notif in buffer]}")
        return self.validation.validate_notification(
            session=session,
            expected_notification=expected_notification,
            timeout=timeout,
            matched=matched,
            notification_expected=notification_expected,
        )

    def collect_all_notifications(self, session, stop_event: threading.Event | None = None) -> list[Notification]:
        """Read the notification buffer until there are no more notifications to collect.

        :param session: Session name.
        :param stop_event: Event to stop reading even if there are notifications remaining (for supervision threads).
        """
        with self.notifications_lock:
            self.notifications_buffer.setdefault(session, [])
            self.supervision_buffer.setdefault(session, [])
            while not stop_event or not stop_event.is_set():
                notification = self.library_wrapper[session].take_notification()
                if not notification:
                    break
                if "supervision-notification" in notification.notification_xml:
                    self.supervision_buffer[session].append(notification)
                else:
                    self.notifications_buffer[session].append(notification)
            return self.notifications_buffer[session]

    def clear_notifications_buffer_for_session(self, session):
        """clear_notifications_buffer_for_session
        :param session:
        :return:
        """
        self.notifications_buffer[session] = []

    def clear_notifications_buffer_for_all_sessions(self):
        """clear_notifications_buffer_for_all_sessions
        :return:
        """
        for session in self.sessions:
            self.notifications_buffer[session] = []

    @staticmethod
    def _calculate_start_and_stop_time(timeout=None):
        if not timeout:
            return None, None
        start = datetime.datetime.utcnow()
        start_time = start.replace(tzinfo=pytz.UTC).isoformat()
        stop = start + datetime.timedelta(seconds=timeout)
        stop_time = stop.replace(tzinfo=pytz.UTC).isoformat()
        return start_time, stop_time

    def get_config(self, session, source):
        """get_config method
        :param session:
        :param source: enum: ["startup", "running", "candidate"]
        :return:
        """
        supported_sources = ["startup", "running", "candidate"]
        if source not in supported_sources:
            raise CommunicationException(
                f"Requested get_config for source: {source} is not in" f" supported list: {supported_sources}"
            )
        output = self.library_wrapper[session].get_config(source)
        self.logger.debug(f"Netconf/Yang get_config for source:{source} response from RM:\n {output}")
        return output

    def get_server_capabilities(self, session):
        """
        :param session:
        :return:
        """
        capabilities_list = self.library_wrapper[session].server_capabilities()
        self.logger.debug(f"Server capabilities: {capabilities_list}")
        return capabilities_list

    def get_client_capabilities(self, session):
        """
        :param session:
        :return:
        """
        capabilities_list = self.library_wrapper[session].client_capabilities()
        self.logger.debug(f"Client capabilities: {capabilities_list}")
        return capabilities_list

    def send_rpc(
        self,
        session,
        msg,
        msg_format: str = "xml",
        validation_mode: str = "deepdiff",
        exclude_paths: Union[None, List[str]] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> tuple[datetime, str]:
        """send rpc
        :param session:
        :param msg:
        :param msg_format:
        :param validation_mode:
        :param exclude_paths:
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
        :return: tuple of (timestamp, content) for the rpc reply
        """
        logger = kwargs.get("logger") or self.logger
        request = msg["request"]
        logger.debug(f"Netconf/Yang rpc msg in xml format send to RM:\n {request}")
        response = self._send_rpc(session, request, msg_format)
        timestamp = getattr(response, "timestamp", datetime.datetime.now().astimezone())  # in case of tls
        if validation_mode == "skip_validation":
            response = str(response)
            logger.debug(f"Output: {response}")
            return timestamp, response
        expected_response = msg.get("expected_response", "<ok/>")
        return timestamp, self.validation.validate_output(
            expected_response=expected_response,
            response=response,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    def _send_rpc(self, session, msg, msg_format="xml"):
        """_send rpc
        :param session:
        :param msg:
        :param msg_format:
        :return:
        """
        if msg_format == "dictionary":
            return self._send_rpc_via_dictionary(session, msg)
        if msg_format == "xml":
            return self._send_rpc_via_xml(session, msg)
        raise CommunicationException(f"{msg_format} is not a supported format.")

    def _send_rpc_via_dictionary(self, session, msg):
        """_send_rpc_via_dictionary
        :param session:
        :param msg:
        :return:
        """
        msg = self.generation.generate_xml_from_dict(msg)
        return self._send_rpc_via_xml(session, msg)

    def _send_rpc_via_xml(self, session, msg):
        """_send_rpc_via_xml
        :param session:
        :param msg:
        :return:
        """
        self.validation.validate_xml(msg)
        msg = lxml.etree.fromstring(msg)
        return self.library_wrapper[session].send_rpc(msg)

    def get_session_id(self, *_, **kwargs) -> int:
        """
        Returns session id
        :return: int, session id
        """
        session = kwargs.get("session")
        session_id = self.library_wrapper[session].get_session_id()
        self.logger.debug(f"Session ID: {session_id}")
        return session_id

    def kill_session(self, session, session_id):
        """
        Kills specified session
        :param session:
        :param session_id:
        :return:
        """
        self.logger.debug(f"Killing session with ID: {session_id}")
        response = self.library_wrapper[session].kill_session(session_id=session_id)
        self.logger.debug(f"Output: {response}")
        return response
